package com.aoo.bcg.common.concurrency;import org.junit.jupiter.api.Test;import java.time.*;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class RoomProgressWatchdogTest{@Test void alertsOnceWhenOperationSeatExistsWithoutSequenceProgressAndRecovers(){var alerts=new ArrayList<RoomProgressWatchdog.StuckRoom>();var w=new RoomProgressWatchdog(Duration.ofSeconds(10),alerts::add);var at=Instant.EPOCH;w.observe(new RoomProgressWatchdog.State(1,2,0,8,at,"PLAY"));w.observe(new RoomProgressWatchdog.State(1,2,0,8,at.plusSeconds(11),"PLAY"));w.observe(new RoomProgressWatchdog.State(1,2,0,8,at.plusSeconds(20),"PLAY"));assertEquals(1,alerts.size());w.observe(new RoomProgressWatchdog.State(1,2,1,9,at.plusSeconds(21),"PLAY"));w.observe(new RoomProgressWatchdog.State(1,2,1,9,at.plusSeconds(32),"PLAY"));assertEquals(2,alerts.size());w.observe(new RoomProgressWatchdog.State(1,2,null,9,at.plusSeconds(40),"SETTLED"));}}
